// Identify which repos have documentation that needs updating
const fs = require('fs');
const path = require('path');
const metaRoot = process.env.HOME + '/Desktop/meta';

// Parse the backlog item to find affected repos
const changedRepos = $json.affected_repos || [];

// Also check all .meta.yaml projects for doc targets
let allTargets = [];
try {
  const metaYamlPath = path.join(metaRoot, '.meta.yaml');
  const content = fs.readFileSync(metaYamlPath, 'utf8');
  const lines = content.split('\n');
  let currentProj = null;
  for (const line of lines) {
    if (/^\s{2}\w+:/.test(line)) {
      currentProj = line.trim().replace(/:.*/, '');
    }
    if (line.includes('repo:') && currentProj) {
      allTargets.push({ repo: currentProj, needs_changelog: true, needs_agents: true });
      currentProj = null;
    }
  }
} catch(e) {}

// Merge with directly changed repos
const docUpdates = [];
for (const repo of [...changedRepos, ...allTargets.map(t => t.repo)]) {
  // Check if CHANGELOG.md exists
  const changelogPath = path.join(metaRoot, repo.replace(/\/home\/drdave\//, '') || '', 'CHANGELOG.md');
  const hasChangelog = fs.existsSync(changelogPath);

  docUpdates.push({
    repo,
    needs_changelog: hasChangelog,
    changelog_path: changelogPath,
    action: 'append_unreleased'
  });
}

return { json: { targets: docUpdates, count: docUpdates.length } };

// Generate changelog entries from the cycle's implementation
const items = $json.items || [];

for (const target of $json.targets) {
  const entries = items.filter(item => 
    item.title && item.title.toLowerCase().includes(target.repo.toLowerCase())
  );

  for (const entry of entries) {
    const category = entry.automation_type === 'n8n_workflow' ? 'chore' : 'feat';
    const prefix = target.repo.replace(/[^a-z]/g, '').slice(0, 10);
    console.log(`[${category}(${prefix}): ${entry.title}]`);
  }
}

return { json: { changelog_entries_generated: true, count: items.length } };

// Check if any decisions need ADR promotion
const WS = process.env.HOME + '/Desktop/meta/n8n/_workspace';
const fs = require('fs');

// Look for decisions in loop state
let adrItems = [];
try {
  const loopStatePath = WS + '/loop_state.md';
  if (fs.existsSync(loopStatePath)) {
    // Check for architecture-level decisions mentioned in backlog
    const backlogPath = WS + '/backlog.md';
    if (fs.existsSync(backlogPath)) {
      const content = fs.readFileSync(backlogPath, 'utf8');
      // Look for items with architecture notes or feature-architect references
      const matches = content.match(/feature-architect|ADR|architecture|decision/g) || [];
      if (matches.length > 0) {
        adrItems = [...new Set(matches)].map((m, i) => ({
          id: `ADR-${String(adrItems.length + 1).padStart(4, '0')}`,
          status: 'pending'
        }));
      }
    }
  }
} catch(e) {}

return { json: { adr_candidates: adrItems } };
